 static InternetSharingController peek(){return instance;}
 static void disarmForGroup(Object source){InternetSharingController c=instance;if(c!=null){Session d=c.donation,u=c.consumption;boolean matched=d!=null&&d.original.source==source||u!=null&&u.original.source==source;if(!matched)return;c.intent.incrementAndGet();if(d!=null&&d.original.source==source){d.explicitStop=true;d.error="";d.stop();}if(u!=null&&u.original.source==source){u.explicitStop=true;u.error="";u.stop();}c.queueHealth();}}
