 static void withdrawForGroup(Object source){InternetSharingController c=instance;if(c==null)return;Session d=c.donation,u=c.consumption;for(Session s:new Session[]{d,u})if(s!=null&&s.original.source==source){if(s.error.isEmpty())s.error="Group connection ended; shared internet is blocked";s.stop();}c.queueHealth();}
