 static final class Offer {
  final String donor,session,host;final int port;final long generation,remaining,until;final InternetSharingScope scope;final BooleanSupplier guard;
  Offer(String donor,String session,String host,int port,long generation,long remaining,long until,InternetSharingScope scope,BooleanSupplier guard){this.donor=donor;this.session=session;this.host=host;this.port=port;this.generation=generation;this.remaining=remaining;this.until=until;this.scope=scope;this.guard=guard;}
  boolean live(long now){return now<until&&remaining>0&&guard.getAsBoolean();}
  JSONObject wire(long now)throws Exception{return new JSONObject().put("protocolVersion",2).put("id",donor).put("sessionId",session).put("generation",generation).put("host",host).put("port",port).put("remainingBytes",remaining).put("expiresInMs",Math.max(0,until-now));}
 }
