 private static String exceptionKind(Exception failed){String type=failed.getClass().getSimpleName();return java.util.Set.of("SocketException","ConnectException","SocketTimeoutException","SSLHandshakeException","SSLException","SecurityException","IOException","IllegalStateException").contains(type)?type:"OtherException";}
 private static String code(Exception failed){if(failed instanceof SecurityException)return "INTERNET_SCOPE_CHANGED";return "INTERNET_UNAVAILABLE";}
 private void queueHealth(){if(!healthQueued.compareAndSet(false,true))return;try{actor.execute(()->{try{health();}finally{healthQueued.set(false);}});}catch(Exception stopped){healthQueued.set(false);}}
 private void foreground(){ActivityManager.RunningAppProcessInfo process=new ActivityManager.RunningAppProcessInfo();ActivityManager.getMyMemoryState(process);if(process.importance!=ActivityManager.RunningAppProcessInfo.IMPORTANCE_FOREGROUND)throw new IllegalStateException("Open AuMaNET to start internet sharing");}
 private InternetSharingScope expected(JSONObject options)throws Exception{InternetSharingScope scope=group.internetScope();if(scope==null||!process.equals(options.getString("processId"))||!scope.group.equals(options.getString("groupId"))||!scope.self.equals(options.getString("selfId"))||scope.epoch!=GroupNameMetadata.number(options,"epoch"))throw new SecurityException();return scope;}
