 private boolean cellValid(Network network){if(network==null)return false;NetworkCapabilities caps=networks.getNetworkCapabilities(network);return caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)&&!caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN)&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);}
